              "ordinal": 0,
              "text": "[Document context]\nTitle: LiteLLM lowest latency routing regression tests for #24720\nSource: Pinned LiteLLM #24720 validation\nPath: /code/litellm/tests/local_testing/test_lowest_latency_routing.py\nWorkspace: task/aisha-litellm-24720-fix\n\n#### What this tests ####\n#    This tests the router's ability to pick deployment with lowest latency\n\nimport asyncio\nimport os\nimport random\nimport sys\nimport time\nimport traceback\nfrom datetime import datetime, timedelta\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nimport copy\nimport os\n\nsys.path.insert(\n    0, os.path.abspath(\"../..\")\n)  # Adds the parent directory to the system path\nimport pytest\n\nimport litellm\nfrom litellm import Router\nfrom litellm.caching.caching import DualCache\nfrom litellm.router_strategy.lowest_latency import LowestLatencyLoggingHandler\n\nfrom tests.fake_openai_endpoint import FAKE_OPENAI_API_BASE\n\n### UNIT TESTS FOR LATENCY ROUTING ###\n\nclass ConcurrentReadDualCache(DualCache):\n    def __init__(self):\n        super().__init__()\n        self.read_count = 0\n        self.both_reads_started = asyncio.Event()\n\nasync def async_get_cache(self, *args, **kwargs):\n        value = await super().async_get_cache(*args, **kwargs)\n        self.read_count += 1\n        if self.read_count == 2:\n            self.both_reads_started.set()\n        try:\n            await asyncio.wait_for(self.both_reads_started.wait(), timeout=0.05)\n        except asyncio.TimeoutError:\n            pass\n        return copy.deepcopy(value)\n\n@pytest.mark.asyncio\nasync def test_concurrent_success_callbacks_can_lose_latency_measurement():\n    test_cache = ConcurrentReadDualCache()\n    lowest_latency_logger = LowestLatencyLoggingHandler(router_cache=test_cache)\n\ndef kwargs_for(deployment_id):\n        return {\n            \"litellm_params\": {\n                \"metadata\": {\"model_group\": \"medium\"},\n                \"model_info\": {\"id\": deployment_id},\n            }\n        }\n\nawait asyncio.gather(\n        lowest_latency_logger.async_log_success_event(kwargs_for(\"deployment-a\"), {}, 0.0, 0.5),\n        lowest_latency_logger.async_log_success_event(kwargs_for(\"deployment-b\"), {}, 0.0, 1.5),\n    )",
