              "ordinal": 1,
              "text": "[Document context]\nTitle: LiteLLM lowest latency routing regression tests for #24720\nSource: Pinned LiteLLM #24720 validation\nPath: /code/litellm/tests/local_testing/test_lowest_latency_routing.py\nWorkspace: task/aisha-litellm-24720-fix\n\n_id},\n            }\n        }\n\nawait asyncio.gather(\n        lowest_latency_logger.async_log_success_event(kwargs_for(\"deployment-a\"), {}, 0.0, 0.5),\n        lowest_latency_logger.async_log_success_event(kwargs_for(\"deployment-b\"), {}, 0.0, 1.5),\n    )\n\ncached_data = await DualCache.async_get_cache(test_cache, key=\"medium_map\")\n    assert set(cached_data) == {\"deployment-a\", \"deployment-b\"}\n\n@pytest.mark.parametrize(\"sync_mode\", [True, False])\n@pytest.mark.asyncio\nasync def test_latency_memory_leak(sync_mode):\n    \"\"\"\n    Test to make sure there's no memory leak caused by lowest latency routing\n\n- make 10 calls -> check memory\n    - make 11th call -> no change in memory\n    \"\"\"\n    test_cache = DualCache()\n    lowest_latency_logger = LowestLatencyLoggingHandler(router_cache=test_cache)\n    model_group = \"gpt-3.5-turbo\"\n    deployment_id = \"1234\"\n    kwargs = {\n        \"litellm_params\": {\n            \"metadata\": {\n                \"model_group\": \"gpt-3.5-turbo\",\n                \"deployment\": \"azure/gpt-4.1-mini\",\n            },\n            \"model_info\": {\"id\": deployment_id},\n        }\n    }\n    start_time = time.time()\n    response_obj = {\"usage\": {\"total_tokens\": 50}}\n    time.sleep(5)\n    end_time = time.time()\n    for _ in range(10):\n        if sync_mode:\n            lowest_latency_logger.log_success_event(\n                response_obj=response_obj,\n                kwargs=kwargs,\n                start_time=start_time,\n                end_time=end_time,\n            )\n        else:\n            await lowest_latency_logger.async_log_success_event(\n                response_obj=response_obj,\n                kwargs=kwargs,\n                start_time=start_time,\n                end_time=end_time,\n            )\n    latency_key = f\"{model_group}_map\"\n    cache_value = copy.deepcopy(\n        test_cache.get_cache(key=latency_key)\n    )  # MAKE SURE NO MEMORY LEAK IN CACHING OBJECT",
